def compress(s: str) -> str:
    """Return the run-length encoding of s, for example "aaabcc" -> "a3b1c2"."""
    if not s:
        return ""

    compressed = []
    count = 1

    for i in range(1, len(s)):
        if s[i] == s[i - 1]:
            count += 1
        else:
            compressed.append(s[i - 1] + str(count))
            count = 1

    compressed.append(s[-1] + str(count))

    return ''.join(compressed)
```

