def second_largest(nums: list[int]) -> int | None:
    """Return the second largest distinct value in nums, or None if there isn't one."""
    if not nums:
        return None

    distinct_nums = set(nums)
    if len(distinct_nums) < 2:
        return None

    first_largest = max(distinct_nums)
    distinct_nums.remove(first_largest)
    return max(distinct_nums)
