def flatten(nested: list) -> list:
    """Return all integers in nested (a list of ints and lists, at any depth) in one list."""
    result = []
    stack = nested[::-1]
    while stack:
        top = stack.pop()
        if isinstance(top, list):
            stack.extend(top[::-1])
        else:
            result.append(top)
    return result[::-1]
