def valid_parentheses(s: str) -> bool:
    """Return True if the brackets ()[]{} in s are properly matched and nested."""
    stack = []
    mapping = {")": "(", "}": "{", "]": "["}

    for char in s:
        if char in mapping.values():
            stack.append(char)
        elif char in mapping:
            if not stack or mapping[char] != stack.pop():
                return False

    return not stack
